cd /home/runner/work/DIV6_cannabis_medicinal_aplicacion/DIV6_cannabis_medicinal_aplicacion && cat >> verde-v3.css <<'CSS'

/* ==========================================================================
   v5 · EXPERIENCIA MÓVIL
   Capa final: navegación, búsqueda, legibilidad, formularios y hojas.
   ========================================================================== */
.mobile-search-btn,.sheet-search,.sheet-backdrop{display:none}

@media(max-width:1120px){
  .mobile-search-btn{display:grid}
}

@media(max-width:960px){
  /* ---- barra superior: título de sección + buscador accesible ---- */
  .topbar{height:auto;min-height:56px;padding:env(safe-area-inset-top) 14px 0;gap:8px}
  .topbar-left{min-width:0;gap:9px}
  .mobile-brand{flex-shrink:0}
  .crumb{display:flex;align-items:center;min-width:0;font:600 9.5px var(--mono);letter-spacing:.12em;color:#9aa48a;margin-left:2px}
  .crumb span,.crumb i{display:none}
  .crumb b{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .topbar-actions{gap:6px;min-width:0}
  .icon-btn{width:38px;height:38px;font-size:15px}
  .mobile-search-btn{width:40px;height:40px;background:rgba(216,242,107,.08);border-color:rgba(216,242,107,.3);color:var(--lime)}
  .mobile-search-btn:active{background:rgba(216,242,107,.2)}

  /* ---- navegación inferior: cómoda y con estado activo ---- */
  .mobile-nav{left:8px;right:8px;bottom:calc(8px + env(safe-area-inset-bottom));padding:7px 5px;border-radius:20px}
  .mobile-nav button{min-height:50px;font-size:9.5px;gap:4px;padding:7px 2px;letter-spacing:.01em}
  .mobile-nav button span{font-size:18px}
  .mobile-nav button.active{background:rgba(216,242,107,.13)}
  .views{padding-bottom:calc(106px + env(safe-area-inset-bottom))}

  /* ---- legibilidad mínima en pantallas chicas ---- */
  .section-kicker{font-size:9px !important}
  .lead{font-size:13.5px !important}
  .is-cell>span:first-child{font-size:8px}
  .is-tag{font-size:8px}
  .idx-kicker,.idx-mini-pill{font-size:8px}
  .idx-card-body p{font-size:11.5px}
  .idx-foot-meta{font-size:8px}
  .north-foot{font-size:8.5px}
  .idx-batch-readout span{font-size:7.5px}
  .idx-batch-readout b{font-size:11px}
  .idx-event-row b{font-size:9px}
  .idx-event-row small,.ie-day{font-size:7.5px}
  .lib-mode small{font-size:9px}
  .budget-sub,.assumption-note,.legal-scale{font-size:9px}

  /* ---- formularios: 16px evita el zoom automático de iOS ---- */
  input,select,textarea{font-size:16px !important}
  .field input,.field select{height:44px}
  .sim-field .select,.sim-field input{height:44px;font-size:16px !important}
  .field>span,.control-row label>span{font-size:10px}
  #commandInput{font-size:16px !important}
  .search-field input{font-size:16px !important}
  .select{min-height:44px}

  /* ---- modales y command palette dentro del viewport ---- */
  .modal-backdrop{padding:calc(10px + env(safe-area-inset-top)) 10px calc(10px + env(safe-area-inset-bottom))}
  .modal{max-height:calc(100dvh - 20px - env(safe-area-inset-top) - env(safe-area-inset-bottom));overflow:auto;overscroll-behavior:contain}
  .command-backdrop{padding:calc(8px + env(safe-area-inset-top)) 8px calc(8px + env(safe-area-inset-bottom))}
  .command-panel{display:flex;flex-direction:column;max-height:calc(100dvh - 16px - env(safe-area-inset-top) - env(safe-area-inset-bottom))}
  .command-input-wrap{padding:12px}
  .command-results{flex:1;max-height:none;overscroll-behavior:contain}
  .cmd-row{padding:11px 10px}
  .cmd-type{width:48px;font-size:7.5px}
  .cmd-copy b{font-size:12px}
  .cmd-copy small{font-size:9px}
  .command-foot{font-size:8.5px;padding:10px 12px}
  .strain-sheet{max-height:calc(100dvh - 20px - env(safe-area-inset-top))}

  /* ---- hoja "Más": backdrop, buscador y cierre por toque ---- */
  .sheet-backdrop{display:block;position:fixed;inset:0;background:rgba(4,6,3,.62);backdrop-filter:blur(4px);opacity:0;pointer-events:none;transition:opacity .25s;z-index:40}
